using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using Mismo.Gameplay.Enemies;using Mismo.Gameplay.Player.Equipment;using Object=UnityEngine.Object;
public static class EnemyEquipmentChecks {
 public static void Run(){Directory.CreateDirectory("output/enemy-equipment");var log=new List<string>();Action<bool,string> check=(v,m)=>{if(!v)throw new Exception(m);log.Add("PASS "+m);};try{
 var root=new GameObject("Enemy");var animator=root.AddComponent<Animator>();var hand=new GameObject("Hand.R");hand.transform.SetParent(root.transform);hand.transform.localPosition=new Vector3(.4f,1,0);
 var integrated=GameObject.CreatePrimitive(PrimitiveType.Cube);integrated.name="OldWeapon";integrated.transform.SetParent(root.transform);var r=integrated.GetComponent<Renderer>();
 var equipment=root.AddComponent<EnemyEquipment>();equipment.animator=animator;equipment.Rebuild();check(equipment.PrimaryVisual==null&&equipment.SecondaryVisual==null,"Unarmed enemy remains unarmed");
 var source=GameObject.CreatePrimitive(PrimitiveType.Cube);source.name="Weapon";equipment.primary.visualPrefab=source;equipment.primary.pose.anchor=WeaponAnchor.BonePath;equipment.primary.pose.bonePath="Hand.R";equipment.primary.pose.offset=new Vector3(.1f,0,0);equipment.hiddenRendererPaths=new[]{"OldWeapon"};equipment.Rebuild();
 check(equipment.PrimaryVisual!=null&&equipment.SecondaryVisual==null,"One optional weapon attaches without requiring a second");check(Vector3.Distance(equipment.PrimaryVisual.position,new Vector3(.5f,1,0))<.001f,"Enemy-specific offset places weapon at chosen bone");check(!equipment.PrimaryVisual.GetComponent<Collider>().enabled,"Visual weapon does not add unintended physical damage");check(!r.enabled,"Integrated old weapon can be hidden");
 hand.transform.localPosition=Vector3.up*2;equipment.ApplyPose();check(Vector3.Distance(equipment.PrimaryVisual.position,new Vector3(.1f,2,0))<.001f,"Weapon follows animated bone position");check(source.transform.position==Vector3.zero,"Source weapon prefab/model is not edited");
 equipment.secondary.visualPrefab=source;equipment.secondary.pose.anchor=WeaponAnchor.BonePath;equipment.secondary.pose.bonePath="Hand.R";equipment.Rebuild();check(equipment.SecondaryVisual!=null,"Second weapon is independently optional");
 equipment.primary.pose.bonePath="Missing";equipment.ApplyPose();check(!equipment.PrimaryVisual.gameObject.activeSelf,"Unresolved anchor hides weapon safely");equipment.primary.pose.bonePath="Hand.R";
 var original=new AnimatorController();var alternate=new AnimatorController();animator.runtimeAnimatorController=original;equipment.controllerOverride=alternate;equipment.Rebuild();check(animator.runtimeAnimatorController==alternate,"Optional controller is applied");equipment.controllerOverride=null;equipment.Rebuild();check(animator.runtimeAnimatorController==original,"Changing override back to empty restores original controller");
 equipment.Release();check(r.enabled&&equipment.PrimaryVisual==null&&equipment.SecondaryVisual==null,"Release restores original visibility and clears equipment");
 equipment.primary.visualPrefab=null;equipment.secondary.visualPrefab=null;equipment.hiddenRendererPaths=Array.Empty<string>();equipment.Rebuild();check(equipment.PrimaryVisual==null,"Returning to unarmed state is supported");
 equipment.Release();Object.DestroyImmediate(root);Object.DestroyImmediate(source);Object.DestroyImmediate(original);Object.DestroyImmediate(alternate);File.WriteAllLines("output/enemy-equipment/checks.txt",log);EditorApplication.Exit(0);
 }catch(Exception e){log.Add("FAIL "+e);File.WriteAllLines("output/enemy-equipment/checks.txt",log);Debug.LogException(e);EditorApplication.Exit(1);}}
}
